//! VOPRF primitives (src/oprf.rs): boundary values, invalid elements, forged proofs, and cross-implementation vectors.
//!
//! - Official RFC 9497 appendix vectors: unit tests in `src/oprf.rs` (`tests/vectors/rfc9497-ristretto255-voprf.json`)
//! - `tests/vectors/oprf-rust.json`: generated here from fixed seeds; the JavaScript reference implementation checks it
//!   against @noble/curves. To regenerate: `GORI_WRITE_VECTORS=1 cargo test --test oprf`
//! - `tests/vectors/oprf-dev.json`: generated by the JavaScript reference implementation with @noble; opened by the unit
//!   tests in `src/oprf.rs`
//!
//! Server operations (`ServerKey`) are behind the `test-server` feature, which the crate's dev-dependency on itself in
//! Cargo.toml enables for tests

use std::path::PathBuf;

use curve25519_dalek::constants::RISTRETTO_BASEPOINT_POINT;
use curve25519_dalek::ristretto::CompressedRistretto;
use curve25519_dalek::scalar::Scalar;
use curve25519_dalek::traits::IsIdentity;
use gori_core::oprf::{self, blind_with, finalize_batch, ServerKey, MAX_BATCH, MAX_INPUT_LEN, PROOF_LEN};
use gori_core::Error;
use rand_chacha::rand_core::{RngCore, SeedableRng};
use rand_chacha::ChaCha20Rng;
use serde::{Deserialize, Serialize};

fn rng(seed: u64) -> ChaCha20Rng {
    ChaCha20Rng::seed_from_u64(seed)
}

fn key(n: u8) -> ServerKey {
    ServerKey::derive(&[n; 32], b"gori-test").unwrap()
}

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap()
}

fn a32(s: &str) -> [u8; 32] {
    h(s).try_into().unwrap()
}

fn x(b: &[u8]) -> String {
    hex::encode(b)
}

fn nonces(n: usize, seed: u64) -> Vec<Vec<u8>> {
    let mut r = rng(seed);
    (0..n)
        .map(|_| {
            let mut v = vec![0u8; 32];
            r.fill_bytes(&mut v);
            v
        })
        .collect()
}

/// Uniform nonzero scalars (wide reduction of 64 bytes): the same distribution as the deterministic blinds the app uses
fn blinds(n: usize, seed: u64) -> Vec<[u8; 32]> {
    let mut r = rng(seed);
    (0..n)
        .map(|_| {
            let mut wide = [0u8; 64];
            r.fill_bytes(&mut wide);
            Scalar::from_bytes_mod_order_wide(&wide).to_bytes()
        })
        .collect()
}

/// Material for one app → server round
struct Round {
    inputs: Vec<Vec<u8>>,
    blinds: Vec<[u8; 32]>,
    blinded: Vec<[u8; 32]>,
    evaluated: Vec<[u8; 32]>,
    proof: [u8; PROOF_LEN],
}

impl Round {
    fn new(k: &ServerKey, n: usize, seed: u64) -> Round {
        let inputs = nonces(n, seed);
        let blinds = blinds(n, seed + 1000);
        let blinded: Vec<[u8; 32]> = inputs.iter().zip(&blinds).map(|(i, b)| blind_with(i, b).unwrap()).collect();
        let (evaluated, proof) = k.blind_evaluate(&mut rng(7), &blinded).unwrap();
        Round { inputs, blinds, blinded, evaluated, proof }
    }

    fn refs(&self) -> Vec<&[u8]> {
        self.inputs.iter().map(|i| i.as_slice()).collect()
    }

    fn finalize(&self, evaluated: &[[u8; 32]], proof: &[u8; PROOF_LEN], pk: &[u8; 32]) -> Result<Vec<[u8; 64]>, Error> {
        finalize_batch(&self.refs(), &self.blinds, &self.blinded, evaluated, pk, proof).map(|o| o.to_vec())
    }
}

// ── Happy path ──

#[test]
fn round_trip_batch_matches_unblinded_evaluate() {
    let k = key(1);
    for n in [1usize, 2, 5, 50, MAX_BATCH] {
        let r = Round::new(&k, n, n as u64);
        let out = r.finalize(&r.evaluated, &r.proof, &k.public_key()).unwrap();
        assert_eq!(out.len(), n);
        for (input, o) in r.inputs.iter().zip(&out) {
            assert_eq!(*k.evaluate(input).unwrap(), *o, "batch {n}");
            assert!(k.verify_output(input, o));
        }
    }
}

/// Blinding the same input with different blinds changes the element the server sees, but not the output
#[test]
fn blinding_hides_the_input_but_output_is_deterministic() {
    let k = key(2);
    let input = b"same-ticket".as_slice();
    let (b1, b2) = (blinds(1, 1)[0], blinds(1, 2)[0]);
    let (e1, e2) = (blind_with(input, &b1).unwrap(), blind_with(input, &b2).unwrap());
    assert_ne!(e1, e2);
    let pk = k.public_key();
    let (ev1, p1) = k.blind_evaluate(&mut rng(1), &[e1]).unwrap();
    let (ev2, p2) = k.blind_evaluate(&mut rng(2), &[e2]).unwrap();
    let o1 = finalize_batch(&[input], &[b1], &[e1], &ev1, &pk, &p1).unwrap();
    let o2 = finalize_batch(&[input], &[b2], &[e2], &ev2, &pk, &p2).unwrap();
    assert_eq!(*o1, *o2);
    assert!(!key(3).verify_output(input, &o1[0]), "a different key gives a different output");
}

// ── Boundary values ──

#[test]
fn input_and_blind_limits() {
    let b = blinds(1, 1)[0];
    assert_eq!(blind_with(b"", &b).err(), Some(Error::TicketInput));
    assert_eq!(blind_with(&vec![1u8; MAX_INPUT_LEN + 1], &b).err(), Some(Error::TicketInput));
    assert!(blind_with(&vec![1u8; MAX_INPUT_LEN], &b).is_ok());
    assert_eq!(blind_with(b"x", &[0u8; 32]).err(), Some(Error::TicketInput), "zero blind");
    assert_eq!(blind_with(b"x", &[0xffu8; 32]).err(), Some(Error::TicketInput), "non-canonical blind");
}

#[test]
fn finalize_shape_checks() {
    let k = key(1);
    let pk = k.public_key();
    let r = Round::new(&k, 3, 3);
    let refs = r.refs();
    // Mismatched counts give TicketInput
    assert_eq!(finalize_batch(&refs, &r.blinds, &r.blinded, &r.evaluated[..2], &pk, &r.proof).err(), Some(Error::TicketInput));
    assert_eq!(finalize_batch(&refs[..2], &r.blinds, &r.blinded, &r.evaluated, &pk, &r.proof).err(), Some(Error::TicketInput));
    assert_eq!(finalize_batch(&[], &[], &[], &[], &pk, &r.proof).err(), Some(Error::TicketInput));
    // Supplied blinded elements that differ from the ones recomputed from the blinds give TicketInput
    let mut wrong = r.blinded.clone();
    wrong.swap(0, 1);
    assert_eq!(finalize_batch(&refs, &r.blinds, &wrong, &r.evaluated, &pk, &r.proof).err(), Some(Error::TicketInput));
    // 65 items
    let k65 = Round::new(&k, MAX_BATCH, 4);
    let mut refs65 = k65.refs();
    refs65.push(b"one more");
    let mut b65 = k65.blinds.clone();
    b65.push(blinds(1, 9)[0]);
    let mut bl65 = k65.blinded.clone();
    bl65.push(blind_with(b"one more", &b65[MAX_BATCH]).unwrap());
    let mut ev65 = k65.evaluated.clone();
    ev65.push(ev65[0]);
    assert_eq!(finalize_batch(&refs65, &b65, &bl65, &ev65, &pk, &k65.proof).err(), Some(Error::TicketInput));
}

